  put(Q.judge("psy-x-123", "psy-drill", "c4", "k1", "维纳把归因分为三个纬度：内部归因与外部归因，稳定性与不稳定性归因、可控性与不可控性归因。（ ）", true, 1, ""), "《判断（彭卷）》");
