  put(Q.short("psy-s-001", "psy-drill", "c1", "k2", "简述高等教育心理学的研究对象与主要内容。", "高等教育心理学研究高等学校教育情境中教与学过程中的心理现象及其规律。主要内容包括：大学生学习心理（学习理论、学习动机、知识学习与迁移、问题解决与创造）、高校教学心理（教学设计、课堂管理、教学评价）、大学生心理发展与心理健康、高校教师心理等。", ["教与学", "学习心理", "教学心理", "心理发展", "教师心理"], 10, ""), "教材自编（第2版）");
  put(Q.short("psy-s-002", "psy-drill", "c3", "k2", "简述奥苏贝尔有意义学习的实质与条件。", "有意义学习的实质是将符号所代表的新知识与学习者认知结构中已有的适当观念建立起非人为的、实质性的联系。条件包括：学习材料具有逻辑意义；学习者具有有意义学习的心向；学习者认知结构中具有同化新知识的适当观念。", ["非人为", "实质性", "逻辑意义", "心向", "适当观念"], 10, ""), "教材自编（第2版）");
  put(Q.short("psy-s-003", "psy-drill", "c4", "k1", "简述耶克斯—多德森定律及其对教学的启示。", "耶克斯—多德森定律表明，动机强度与学习效率呈倒U形关系，中等强度的动机最有利于学习；任务越难，最佳动机水平越低。教学启示：要根据任务难度调节学生的动机水平，避免过度焦虑或动机不足。", ["倒U", "中等", "任务难度", "动机水平"], 10, ""), "教材自编（第2版）");
  put(Q.short("psy-s-004", "psy-drill", "c9", "k1", "简述促进学习迁移的教学策略。", "一是精选具有广泛迁移价值的教材；二是合理编排教学内容，突出知识间的联系；三是教授学习策略与方法，提高概括水平；四是创设相似的应用情境，加强练习与反馈；五是帮助学生形成积极的迁移心向。", [["精选教材", "迁移价值的教材"], "编排", "学习策略", ["相似情境", "相似的应用情境"], "迁移心向"], 10, ""), "教材自编（第2版）");
  put(Q.short("psy-s-005", "psy-drill", "c6", "k1", "简述问题解决的一般过程及影响问题解决的主要因素。", "问题解决一般经历发现问题、分析问题、提出假设、检验假设四个阶段。影响因素包括：问题的表征方式、知识经验、思维定势与功能固着、动机与情绪状态、原型启发等。", ["发现问题", "提出假设", "检验假设", "定势", "功能固着", "原型启发"], 10, ""), "教材自编（第2版）");
  put(Q.short("psy-s-006", "psy-drill", "c2", "k1", "简述科尔伯格道德发展阶段理论的基本内容。", "科尔伯格用道德两难故事法，将道德发展分为三水平六阶段：前习俗水平（惩罚与服从、相对功利）、习俗水平（好孩子、维护权威秩序）、后习俗水平（社会契约、普遍伦理）。道德发展具有顺序性、不可逆性。", ["三水平", "前习俗", "习俗水平", "后习俗", "顺序性"], 10, ""), "教材自编（第2版）");
  put(Q.short("psy-s-007", "psy-drill", "c11", "k2", "简述大学生自我意识发展的特点及教育对策。", "特点：自我认识更主动、自我体验更丰富敏感、自我调控能力增强，但容易出现自我同一性困惑、理想我与现实我冲突。对策：开展自我意识教育，引导正确认识与评价自我；创设成功体验，增强自我效能感；加强个别辅导，帮助整合自我概念。", ["自我认识", "自我体验", "自我调控", "同一性", "自我效能"], 10, ""), "教材自编（第2版）");
  put(Q.short("psy-s-008", "psy-drill", "c13", "k1", "简述教师期望效应及其教育启示。", "教师期望效应又称罗森塔尔效应或皮格马利翁效应，指教师对学生的期望通过态度、表情、提问与反馈等方式传递，使学生朝着期望的方向发展。启示：教师应对学生抱有积极合理的期望，避免消极标签，关注每个学生的潜能。", ["罗森塔尔", "期望", "标签", "潜能"], 10, ""), "教材自编（第2版）");
  put(Q.short("psy-s-009", "psy-drill", "c11", "k1", "简述大学生心理健康教育的主要途径。", "一是开设心理健康教育课程与讲座；二是开展心理测评，建立心理档案；三是提供个体咨询与团体辅导；四是构建学校—院系—班级三级预警与干预网络；五是营造积极校园文化，加强家校协同。", ["课程", "心理测评", ["心理咨询", "个体咨询"], "预警", "家校"], 10, ""), "教材自编（第2版）");
  put(Q.blank("psy-f-001", "psy-drill", "c5", "k2", "艾宾浩斯遗忘曲线表明，遗忘的进程是____的，表现为先快后慢。", ["不均衡"], 2, ""), "教材自编（第2版）");
