  put(Q.blank("psy-f-006", "psy-drill", "c3", "k2", "布鲁纳主张让学生通过独立思考、自己发现知识，这种方法称为____法。", ["发现"], 2, ""), "教材自编（第2版）");
  put(Q.short("psy-n-001", "psy-main", "c3", "k1", "比较正强化、负强化与惩罚。", "正强化是增加一种结果以提高行为发生概率；负强化是撤除厌恶刺激以提高行为发生概率；惩罚旨在降低行为发生概率。区分的关键是行为增加还是减少，以及刺激增加还是撤除，不能把负强化直接等同于惩罚。", ["提高行为发生概率", "厌恶刺激", "降低行为发生概率", "撤除"], 10, "自编练习：结合题目要求分点作答，机评仅供参考，可对照参考答案自评。"), "教育理论知识点自编");
  put(Q.short("psy-n-002", "psy-main", "c3", "k1", "如何使用先行组织者帮助学生学习新知识？", "先分析学生已有知识与新内容的联系；在具体材料之前提供概括性较高的概念框架或比较线索；学习中引导学生把新知识与已有知识建立联系；通过例子、解释与应用检查理解，避免只让学生机械背诵框架。", ["已有知识", "概念框架", "联系", "检查理解"], 10, "自编练习：结合题目要求分点作答，机评仅供参考，可对照参考答案自评。"), "教育理论知识点自编");
